"""Owned-instance checkpoint preparation, injected failures and actual mate/motion acceptance."""
import argparse, hashlib, json, os, subprocess, time, uuid
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
CS='using System;using System.IO;using System.Linq;using System.Threading;using System.Collections.Generic;using SolidWorks.Interop.sldworks;using SolidWorks.Interop.swmotionstudy;\npublic partial class Cad {\n public object ProbeTestStates(string id){using(var s=new Scope(this,GetUserModel(id).Path,null))return StudyStates(s.Doc);}\n public object ProbeTestOnly(string id){var cp=Json.Deserialize<Dictionary<string,object>>(Json.Serialize(CreateUserCheckpoint(id)));var m=GetUserModel(id);using(var s=new Scope(this,m.Path,null))return CheckAnimationCheckpoint(m,(string)cp["checkpoint_id"]);}\n public void ProbeTestAnimation(string id){using(var s=new Scope(this,GetUserModel(id).Path,null)){var mgr=(IMotionStudyManager)s.Doc.Extension.GetMotionStudyManager();var study=(IMotionStudy)mgr.GetMotionStudy(Names(mgr).First());if(!study.Activate()&&!study.IsActive)throw new Exception("TEST_ANIMATION_ACTIVATION_FAILED");study.SetDuration(1);((IMotionStudyProperties)study.GetProperties(1)).SetFrameRate(30);if(!study.Calculate())throw new Exception("TEST_ANIMATION_CALCULATE_FAILED");study.Stop();study.SetTime(0);if(Math.Abs(study.GetTime())>1e-8)throw new Exception("TEST_ANIMATION_NOT_ZERO");SaveOwnedDocuments(GetUserModel(id));}}\n public void ProbeTestPoseDrift(IModelDoc2 doc){var before=Transforms(doc);ProbeTestClockDrift(doc);var change=Json.Deserialize<Dictionary<string,object>>(Json.Serialize(PoseChange(before,Transforms(doc))));if(Convert.ToDouble(change["maximum_translation_m"])<1e-6&&Convert.ToDouble(change["maximum_rotation_rad"])<1e-5)throw new Exception("TEST_POSE_DRIFT_NOT_OBSERVED");Log("CONTROLLED_REAL_POSE_DRIFT "+Json.Serialize(change));}\n public void ProbeTestClockDrift(IModelDoc2 doc){var mgr=(IMotionStudyManager)doc.Extension.GetMotionStudyManager();var study=Names(mgr).Select(n=>(IMotionStudy)mgr.GetMotionStudy(n)).Single(s=>s.IsActive);study.SetTime(.5);if(Math.Abs(study.GetTime()-.5)>1e-8)throw new Exception("TEST_CLOCK_DRIFT_NOT_OBSERVED");}\n public object ProbeTestCounts(string id){var m=GetUserModel(id);using(var s=new Scope(this,m.Path,null))return new{mate_count=UserMates(s.Doc).Length,studies=StudyStates(s.Doc),sources_unchanged=UserSourcesUnchanged(m)};}\n public void ProbeTestCloseProbeFiles(){var docs=(Sw.GetDocuments() as object[]??new object[0]).Cast<IModelDoc2>().Where(d=>d.GetPathName().StartsWith(Root+Path.DirectorySeparatorChar,StringComparison.OrdinalIgnoreCase)&&d.GetPathName().IndexOf("cp-probes",StringComparison.OrdinalIgnoreCase)>=0).Select(d=>d.GetPathName()).ToArray();CloseUserDocuments(docs);}\n public void ProbeTestExit(int pid){if(Sw.GetProcessID()!=pid)throw new Exception("OWNED_PID_MISMATCH");var docs=(Sw.GetDocuments() as object[]??new object[0]).Cast<IModelDoc2>().ToArray();if(docs.Any(d=>!d.GetPathName().StartsWith(Root+Path.DirectorySeparatorChar,StringComparison.OrdinalIgnoreCase)))throw new Exception("NON_OWNED_DOCUMENT_REFUSE_EXIT");CloseUserDocuments(docs.Select(d=>d.GetPathName()).ToArray());Sw.ExitApp();}\n}\nclass ProbeAcceptance {\n static Dictionary<string,object> D(object x){return Cad.Json.Deserialize<Dictionary<string,object>>(Cad.Json.Serialize(x));}\n static Dictionary<string,object>[] Rows(object x){return Cad.Json.Deserialize<Dictionary<string,object>[]>(Cad.Json.Serialize(x));}\n static void Require(bool v,string n){if(!v)throw new Exception(n);}\n static Dictionary<string,object> Plan(Cad cad,string id){var rows=Rows(D(cad.ListMateReferences(id,"","cylindrical_axis",50,null))["entities"]);var a=rows.First(r=>(bool)r["fixed_component"]);var b=rows.First(r=>!(bool)r["fixed_component"]);return D(cad.PreviewBasicMate(id,(string)a["entity_id"],(string)b["entity_id"],"concentric","aligned",0,false,""));}\n [STAThread]static int Main(string[] args){string root=Path.GetFullPath(args[0]);int pid=int.Parse(args[2]);Cad cad=null;var report=new Dictionary<string,object>{{"completed",false},{"steps",new List<object>()}};Action save=()=>File.WriteAllText(Path.Combine(root,"native.json"),Cad.Json.Serialize(report));Action<string,object> record=(n,d)=>{((List<object>)report["steps"]).Add(new{name=n,data=d});save();Cad.Log("PROBE_ACCEPTANCE "+n);};\n using(var gate=new Mutex(false,"Local\\\\SolidWorksClashMate_MechDog_Executor")){if(!gate.WaitOne(0))return 4;try{\n cad=new Cad(root);Require(cad.Sw.GetProcessID()==pid&&(cad.Sw.GetDocuments() as object[]??new object[0]).Length==0,"OWNED_INSTANCE_NOT_EMPTY");\n foreach(bool firstLast in new[]{true,false}){var imported=D(cad.ImportUserAssembly(args[1],""));string id=(string)imported["model_id"];var states=Cad.Json.Deserialize<Cad.StudyState[]>(Cad.Json.Serialize(cad.ProbeTestStates(id)));foreach(var state in states.OrderBy(s=>s.name==(firstLast?states.First().name:states.Last().name)?1:0))cad.ResetUserStudyTime(id,state.name,true);record(firstLast?"slider_first_study_last":"slider_second_study_last",cad.ProbeTestOnly(id));if(firstLast){bool drift=false;cad.CheckpointProbeTestHook=(stage,doc)=>{if(stage=="after_probe_close"&&!drift){drift=true;cad.ProbeTestPoseDrift(doc);}};try{var recovery=D(cad.ProbeTestOnly(id));Require(drift&&(bool)recovery["context_restore_performed"]&&(bool)recovery["original_copy_verified"],"REAL_POSE_RECOVERY_NOT_VERIFIED");record("slider_real_pose_context_restored",recovery);}finally{cad.CheckpointProbeTestHook=null;}}}\n string template=Path.Combine(args[3],"rotary_unmated.SLDASM");\n foreach(string mode in new[]{"safe_failure","context_restored","restore_failure","cleanup_failure","post_add_fault","positive"}){\n var imported=D(cad.ImportUserAssembly(template,""));string id=(string)imported["model_id"];cad.ProbeTestAnimation(id);var plan=Plan(cad,id);bool injected=false;\n cad.CheckpointProbeTestHook=(stage,doc)=>{\n if(mode=="safe_failure"&&stage=="before_copy")throw new CadFault("CONTROLLED_PROBE_FAILURE","Controlled preparation failure");\n if((mode=="context_restored"||mode=="restore_failure")&&stage=="after_probe_close"&&!injected){injected=true;cad.ProbeTestClockDrift(doc);}\n if(mode=="restore_failure"&&stage=="before_context_restore")throw new CadFault("CONTROLLED_CONTEXT_RESTORE_FAILURE","Controlled restoration failure");\n if(mode=="cleanup_failure"&&stage=="before_probe_close")throw new CadFault("CONTROLLED_PROBE_CLEANUP_FAILURE","Controlled cleanup failure");};\n try{var applied=D(cad.ApplyBasicMate((string)plan["plan_id"],true,mode=="post_add_fault"));Require(mode=="positive"||mode=="context_restored","FAILURE_CASE_COMMITTED");Require(Convert.ToInt32(applied["mate_count_after"])==1&&Convert.ToInt32(applied["mate_count_before"])==0&&(bool)D(applied["native_parameters"])["verified"],"POSITIVE_MATE_UNVERIFIED");\n if(mode=="context_restored"){Require(injected&&(bool)D(applied["checkpoint_probe"])["context_restore_performed"],"CONTEXT_RESTORATION_NOT_EXERCISED");}\n record(mode,applied);\n if(mode=="positive"){var inspect=D(cad.InspectUserModel(id));var moving=Rows(inspect["mates"]).SelectMany(m=>Rows(m["entities"])).Where(e=>e.ContainsKey("geometry")).Select(e=>D(e["geometry"])).First(e=>!(bool)e["fixed_component"]);string component=(string)moving["component_id"],entity=(string)moving["entity_id"];cad.CreateUserStudy(id,"ProbeVerifiedMotion",component,entity,"rotary",30,false,"",2,30);var motion=D(cad.VerifyRequestedMotion(id,"ProbeVerifiedMotion",component,entity,"rotary",360,2,30,Guid.NewGuid().ToString("N"),""));Require((string)motion["assertion"]=="pass","NEW_MATE_DID_NOT_PRESERVE_ROTATION");record("positive_motion_preservation_360",motion);}\n }catch(CadFault failure){if(mode=="positive"||mode=="context_restored")throw;var d=D(failure.Diagnostics);bool safe=mode=="safe_failure"||mode=="post_add_fault";Require(safe?cad.LastOperationRestoration=="restored":cad.LastOperationRestoration=="unknown","WRONG_PREPARATION_RESTORATION_STATUS");Require(safe?(bool)d["rollback_verified"]:!(bool)d["rollback_verified"],"FALSE_ROLLBACK_VERIFICATION");if(mode!="post_add_fault")Require(!(bool)d["mate_created"],"ADDMATE_OCCURRED_DURING_PREPARATION_FAILURE");record(mode,new{code=failure.Code,details=d,last_operation_restoration=cad.LastOperationRestoration});\n cad.CheckpointProbeTestHook=null;cad.ProbeTestCloseProbeFiles();if(!safe)record(mode+"_explicit_restore",cad.RestoreUserCheckpoint(id,(string)d["checkpoint_id"]));Require(Convert.ToInt32(D(cad.ProbeTestCounts(id))["mate_count"])==0,"FAILED_MATE_PERSISTED");\n try{cad.ApplyBasicMate((string)plan["plan_id"],true);throw new Exception("CONSUMED_PLAN_REUSED");}catch(CadFault e){Require(e.Code=="MATE_PLAN_CONSUMED","CONSUMED_PLAN_ERROR_CHANGED");}\n }finally{cad.CheckpointProbeTestHook=null;}\n }\n report["completed"]=true;save();return 0;\n }catch(Exception e){report["error"]=e.ToString();report["details"]=e is CadFault?((CadFault)e).Diagnostics:null;save();return 1;}finally{if(cad!=null)try{cad.ProbeTestExit(pid);report["owned_exit_requested"]=true;}catch(Exception e){report["cleanup_error"]=e.ToString();}save();gate.ReleaseMutex();}}\n }\n}'

def main():
 parser=argparse.ArgumentParser();parser.add_argument('--source',required=True);parser.add_argument('--examples',required=True);args=parser.parse_args();source=Path(args.source).resolve()
 if not source.is_file() or source.suffix.lower()!='.sldasm':raise ValueError('Specify the saved test assembly')
 if not (Path(args.examples)/'examples.json').is_file() or not (Path(args.examples)/'rotary_unmated.SLDASM').is_file():raise ValueError('Use program-generated examples with examples.json and rotary_unmated.SLDASM')
 folder=ROOT/'runs/checkpoint-probe-acceptance'/uuid.uuid4().hex[:8];folder.mkdir(parents=True);(folder/'test.cs').write_text(CS,encoding='utf-8')
 redist=Path(os.environ.get('SW_INSTALL_DIR',r'C:\Program Files\SOLIDWORKS Corp\SOLIDWORKS'))/'api/redist';dlls=('SolidWorks.Interop.sldworks.dll','SolidWorks.Interop.swconst.dll','SolidWorks.Interop.swmotionstudy.dll')
 for n in dlls:(folder/n).write_bytes((redist/n).read_bytes())
 exe=folder/'ProbeAcceptance.exe';command=[str(Path(os.environ['WINDIR'])/'Microsoft.NET/Framework64/v4.0.30319/csc.exe'),'/nologo','/platform:x64','/main:ProbeAcceptance','/reference:System.Web.Extensions.dll','/reference:System.Windows.Forms.dll','/reference:Microsoft.CSharp.dll','/out:'+str(exe)]+['/reference:'+str(redist/n) for n in dlls]+[str(p) for p in (ROOT/'executor').glob('*.cs')]+[str(folder/'test.cs')];subprocess.run(command,check=True)
 hashes={str(p):hashlib.sha256(p.read_bytes()).hexdigest() for folder_source in (source.parent,Path(args.examples)) for p in folder_source.iterdir() if p.is_file()};journal=ROOT/'runs/executor-state.json';journal_hash=hashlib.sha256(journal.read_bytes()).hexdigest()
 report={'completed':False,'directory':str(folder),'source_hashes':hashes,'primary_journal_sha256':journal_hash};save=lambda:(folder/'session.json').write_text(json.dumps(report,ensure_ascii=False,indent=2),encoding='utf-8')
 startup=subprocess.STARTUPINFO();startup.dwFlags|=subprocess.STARTF_USESHOWWINDOW;startup.wShowWindow=0;owned=subprocess.Popen([str(redist.parents[1]/'SLDWORKS.exe')],startupinfo=startup);report['owned_pid']=owned.pid;save();print('OWNED_INSTANCE',owned.pid,str(folder),flush=True);env={**os.environ,'SW_MCP_PROCESS_ID':str(owned.pid),'SW_MCP_FAULT_TESTS':'1'};deadline=time.monotonic()+180
 while True:
  if owned.poll() is not None:raise RuntimeError('Owned application exited before connection')
  check=subprocess.run([str(ROOT/'executor/bin/SwExecutor.exe'),'check-connection'],env=env,capture_output=True,timeout=25);hello=json.loads(check.stdout);report['connection']=hello;save()
  if hello.get('ready'):assert hello['process_id']==owned.pid;break
  if time.monotonic()>deadline:raise TimeoutError('COM startup pending')
  time.sleep(2)
 with (folder/'stdout.log').open('wb') as out,(folder/'stderr.log').open('wb') as err:
  helper=subprocess.Popen([str(exe),str(folder),str(source),str(owned.pid),str(Path(args.examples).resolve())],env=env,stdout=out,stderr=err,creationflags=subprocess.CREATE_NO_WINDOW);report['helper_pid']=helper.pid;save();helper.wait(timeout=900)
 report.update(helper_exit=helper.returncode,source_files_unchanged=all(hashlib.sha256(Path(p).read_bytes()).hexdigest()==h for p,h in hashes.items()),primary_journal_unchanged=hashlib.sha256(journal.read_bytes()).hexdigest()==journal_hash)
 try:owned.wait(timeout=45);report['owned_exit_code']=owned.returncode
 except subprocess.TimeoutExpired:report['owned_exit_pending']=True
 report['completed']=helper.returncode==0 and report['source_files_unchanged'] and report['primary_journal_unchanged'];save();(ROOT/'runs/checkpoint-probe-acceptance-latest.json').write_text(json.dumps(report,ensure_ascii=False,indent=2),encoding='utf-8');print(json.dumps({k:v for k,v in report.items() if k not in ('source_hashes','connection')},ensure_ascii=True),flush=True)
if __name__=='__main__':main()
